export function validateComment(comment: string) {
  if (!comment.trim()) {
    return { ok: false, error: 'Comment is required' }
  }

  return { ok: true }
}

css:
.rollout-track {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px;
  padding: 22px;
  background: var(--artifact-code);
}

.rollout-step {
  padding: 16px 18px;
  background: var(--artifact-code-raised);
  border-top: 3px solid var(--artifact-code-border);
}

.rollout-step.is-done {
  border-top-color: var(--artifact-positive);
}

.rollout-name {
  margin: 0;
  color: var(--artifact-code-ink);
  font-weight: 600;
  font-size: 17px;
}

.rollout-note {
  margin: 6px 0 0;
  color: var(--artifact-code-muted);
  font-size: 16px;
}
